/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension.Used for identify caller
/// </summary>
/// <param name = "_contract">_contract</param>
protected void initializeRebatePostContract(TAMRebatePostContract _contract)
{
    if (this.parmArgs().caller())
    {
        _contract.parmIsCalledFromMainBatchJob(false);
    }
    next initializeRebatePostContract(_contract);
}
